components.css:
.ds-button-primary { display:inline-flex; min-height:48px; align-items:center; justify-content:center; gap:12px; padding:13px 18px; border:1px solid var(--accent, #2858cc); border-radius:0; background:var(--accent, #2858cc); color:var(--paper-strong, #fffefa); font:500 13px/1.4 "Manrope",sans-serif; text-decoration:none; transition:transform .2s cubic-bezier(.16,1,.3,1), background .2s ease, border-color .2s ease; }
.ds-button-primary:hover { transform:translateY(-2px); border-color:var(--accent-deep, #1d4299); background:var(--accent-deep, #1d4299); }
.ds-button-primary:focus-visible { outline:3px solid var(--accent, #2858cc); outline-offset:4px; }

.ds-button-secondary { display:inline-flex; min-height:48px; align-items:center; justify-content:center; padding:13px 18px; border:1px solid var(--line, #cfd5df); border-radius:0; background:transparent; color:var(--ink, #182230); font:500 13px/1.4 "Manrope",sans-serif; text-decoration:none; transition:transform .2s cubic-bezier(.16,1,.3,1), color .2s ease, border-color .2s ease; }
.ds-button-secondary:hover { transform:translateY(-2px); border-color:var(--accent, #2858cc); color:var(--accent-deep, #1d4299); }
.ds-button-secondary:focus-visible { outline:3px solid var(--accent, #2858cc); outline-offset:4px; }

.ds-nav { display:flex; align-items:center; flex-wrap:wrap; gap:clamp(20px,3vw,42px); font-family:"Manrope",sans-serif; }
.ds-nav a { display:inline-flex; min-height:44px; align-items:center; color:var(--muted, #596575); font-size:13px; font-weight:500; text-decoration:none; transition:color .2s ease; }
.ds-nav a:hover { color:var(--accent-deep, #1d4299); }
.ds-nav .ds-nav-cta { padding:12px 17px; background:var(--accent, #2858cc); color:var(--paper-strong, #fffefa); transition:background .2s ease, transform .2s cubic-bezier(.16,1,.3,1); }
.ds-nav .ds-nav-cta:hover { background:var(--accent-deep, #1d4299); color:var(--paper-strong, #fffefa); transform:translateY(-2px); }
.ds-nav a:focus-visible { outline:3px solid var(--accent, #2858cc); outline-offset:4px; }
@media (max-width:760px) { .ds-nav { align-items:stretch; flex-direction:column; gap:0; } .ds-nav a { padding:15px 3px; border-bottom:1px solid var(--line, #cfd5df); font-size:14px; } .ds-nav .ds-nav-cta { justify-content:center; margin-top:12px; padding:13px 15px; border:0; } }

.ds-project-facts { display:grid; gap:9px; margin:0; padding:16px 0; border-bottom:1px solid var(--line, #cfd5df); font-family:"Manrope",sans-serif; }
.ds-project-facts div { display:grid; grid-template-columns:72px minmax(0,1fr); gap:14px; }
.ds-project-facts dt { color:var(--accent-deep, #1d4299); font-size:12px; font-weight:500; }
.ds-project-facts dd { margin:0; color:var(--muted, #596575); font-size:13px; line-height:1.6; }

.ds-contact-panel { position:relative; overflow:hidden; display:grid; grid-template-columns:1fr auto; align-items:end; gap:35px; padding:clamp(38px,6vw,76px); border-radius:0; background:var(--ink, #182230); color:var(--paper-strong, #fffefa); font-family:"Manrope",sans-serif; }
.ds-contact-panel h2 { max-width:740px; margin:0 0 15px; font-size:clamp(32px,4.8vw,58px); font-weight:700; line-height:1.05; letter-spacing:-.04em; }
.ds-contact-panel p { max-width:620px; margin:0; color:#e0e5ee; font-size:15px; line-height:1.75; }
.ds-contact-button { display:inline-flex; min-height:48px; align-items:center; justify-content:center; padding:13px 18px; border:1px solid var(--paper-strong, #fffefa); background:var(--paper-strong, #fffefa); color:var(--ink, #182230); font-size:13px; font-weight:500; white-space:nowrap; text-decoration:none; transition:background .2s ease, border-color .2s ease, color .2s ease, transform .2s cubic-bezier(.16,1,.3,1); }
.ds-contact-button:hover { transform:translateY(-2px); border-color:#9db8ff; background:var(--accent, #2858cc); color:#fff; }
.ds-contact-button:focus-visible { outline:3px solid var(--accent, #2858cc); outline-offset:4px; }
@media (max-width:760px) { .ds-contact-panel { grid-template-columns:1fr; align-items:start; gap:25px; padding:34px 24px; } }
